changeSet.sql:
-- Append-only, hash-chained audit log. Partitioned monthly. -- No UPDATE/DELETE granted at role level in prod (enforced by revoke). CREATE TABLE audit.audit_logs ( id BIGSERIAL, tenant_id UUID NOT NULL, trace_id UUID, user_id UUID, impersonator_user_id UUID, service VARCHAR(50) NOT NULL, module VARCHAR(50) NOT NULL, entity_type VARCHAR(50) NOT NULL, entity_id VARCHAR(100) NOT NULL, action VARCHAR(30) NOT NULL, changes JSONB, metadata JSONB, prev_hash BYTEA, record_hash BYTEA, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (id, created_at) ) PARTITION BY RANGE (created_at);
-- Sample partitions (pg_partman will manage rest) CREATE TABLE audit.audit_logs_2026_07 PARTITION OF audit.audit_logs FOR VALUES FROM ('2026-07-01') TO ('2026-08-01'); CREATE TABLE audit.audit_logs_2026_08 PARTITION OF audit.audit_logs FOR VALUES FROM ('2026-08-01') TO ('2026-09-01');
CREATE INDEX idx_audit_tenant_entity ON audit.audit_logs(tenant_id, entity_type, entity_id, created_at DESC); CREATE INDEX idx_audit_user_time ON audit.audit_logs(tenant_id, user_id, created_at DESC);

ALTER TABLE audit.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON audit.audit_logs
  USING (tenant_id = COALESCE(
    NULLIF(current_setting('app.current_tenant_id', true), ''),
    '00000000-0000-0000-0000-000000000000'
  )::uuid);

ALTER TABLE audit.chain_verification_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON audit.chain_verification_runs
  USING (tenant_id = COALESCE(
    NULLIF(current_setting('app.current_tenant_id', true), ''),
    '00000000-0000-0000-0000-000000000000'
  )::uuid);
